UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp2-6543cr-al19-ft.pdf',
  descripcion_larga_es = $d$El Cómodo Sanitario Plegable con Ruedas de Aluminio KP2-6543CR-AL19 está diseñado para brindar un soporte seguro y cómodo a personas con dificultades para el desplazamiento. Fabricado en aluminio pintado, este cómodo sanitario es ligero, resistente y fácil de manejar. Su diseño plegable lo hace ideal para espacios reducidos, permitiendo un almacenamiento y transporte sencillos. Equipado con ruedas de 3,8 pulgadas de plástico, facilita la movilidad en interiores sin esfuerzo.

El cómodo sanitario de aluminio con ruedas de 120 kg Konfort Plus tiene estructura de aluminio pintado, aro plástico, respaldo de tela lavable, balde con tapa y extensión con rueda y freno. Mide entre 97 y 102 cm de alto, tiene asiento de 43 x 43 cm y es clase I (riesgo bajo) con registro 2018DM-0018624.$d$,
  descripcion_larga_en = $d$The Konfort Plus Folding Commode Chair on Wheels KP2-6543CR-AL19 is designed to provide safe and comfortable support for individuals with mobility difficulties. Constructed from painted aluminum, this commode is lightweight, durable, and easy to handle. Its foldable design makes it ideal for compact spaces, allowing simple storage and transport. Equipped with 3.8-inch plastic wheels, it facilitates effortless indoor mobility.

The Konfort Plus 120 kg aluminium commode with wheels has a painted aluminium frame, plastic ring seat, washable fabric backrest, a bucket with lid and an extension with wheel and brake. It stands 97 to 102 cm high, has a 43 x 43 cm seat and is class I (low risk) with registration 2018DM-0018624.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP2-6543CR-AL19"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"120 kg"},{"clave":"Altura","grupo":"Dimensiones","valor":"97 - 102 cm"},{"clave":"Ruedas","grupo":"Ruedas","valor":"3,8\" de plástico"},{"clave":"Registro sanitario","grupo":"Regulatorio","valor":"2018DM-0018624; clase I"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Capacidad de 120 kg sobre estructura de aluminio pintado.","Respaldo de tela lavable, aro plástico y balde con tapa.","Extensión con rueda y freno; altura de 97 a 102 cm."],"beneficios_en":["120 kg capacity on a painted aluminium frame.","Washable fabric backrest, plastic ring and bucket with lid.","Extension with wheel and brake; height from 97 to 102 cm."],"valor_es":"Un cómodo sanitario con ruedas para pacientes de hasta 120 kg.","valor_en":"A commode with wheels for patients up to 120 kg.","preguntas_frecuentes_es":[{"q":"¿Qué peso soporta?","a":"120 kg."},{"q":"¿Tiene tapa el balde?","a":"Sí, balde con tapa."},{"q":"¿Qué altura tiene?","a":"De 97 a 102 cm."},{"q":"¿Dónde descargo la ficha técnica de Cómodo Sanitario En Aluminio Anodizado Con Ruedas de 120 kg Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What weight does it support?","a":"120 kg."},{"q":"Does the bucket have a lid?","a":"Yes, bucket with lid."},{"q":"What height does it have?","a":"From 97 to 102 cm."},{"q":"Where can I download the Konfort Plus Folding Commode Chair on Wheels 120 kg Aluminum Anodized datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["cómodo sanitario con ruedas 120 kg","silla sanitaria con ruedas de aluminio","cómodo con balde y tapa","cómodo Konfort Plus","sillas sanitarias Colombia","ficha técnica KP2-6543CR-AL19"],"seo_keywords_en":["120 kg commode with wheels","aluminium commode chair with wheels","commode with bucket and lid","Konfort Plus commode","commode chairs Colombia","KP2-6543CR-AL19 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCEHCZYTKRRFDQJFZQFHHK4NWE6A?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
