UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp1-3520l-ft.pdf',
  descripcion_larga_es = $d$La Silla para Ducha con Brazos Konfort Plus está diseñada para ofrecer seguridad y comodidad durante el baño. Fabricada en aluminio, esta silla es ligera y fácil de transportar, además de resistente gracias a su estructura. El asiento y respaldo en polietileno de alta densidad son duraderos y fáciles de limpiar, garantizando una larga vida útil y un mantenimiento sencillo.

La silla para ducha con brazos Konfort Plus es de aluminio desarmable mediante pines y tornillos, con asiento y respaldo de polietileno de alta densidad, altura regulable de 41 a 54 cm, apoyabrazos y capacidad de 130 kg. Pesa 3,2 kg y es clase I (riesgo bajo), con registro sanitario 2018DM-0018624.$d$,
  descripcion_larga_en = $d$The Konfort Plus Shower Chair with Arms is designed to provide safety and comfort during bathing. Constructed from aluminum, this chair is lightweight and easy to transport, while its frame ensures structural resistance. The high-density polyethylene seat and backrest are durable and easy to clean, guaranteeing a long service life and simple maintenance.

The Konfort Plus shower chair with arms is aluminium that can be taken apart with pins and screws, with a high-density polyethylene seat and backrest, adjustable height from 41 to 54 cm, armrests and a 130 kg capacity. It weighs 3.2 kg and is class I (low risk), with health registration 2018DM-0018624.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP1-3520L"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"130 kg"},{"clave":"Peso del producto","grupo":"Peso","valor":"3,2 kg"},{"clave":"Estructura / asiento","grupo":"Material","valor":"Aluminio / polietileno de alta densidad"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aluminio desarmable, de solo 3,2 kg, fácil de guardar.","Asiento y respaldo de polietileno de alta densidad con brazos.","Altura regulable y capacidad de 130 kg."],"beneficios_en":["Take-apart aluminium, only 3.2 kg, easy to store.","High-density polyethylene seat and backrest with arms.","Adjustable height and 130 kg capacity."],"valor_es":"Una silla de ducha ligera con brazos y capacidad de 130 kg.","valor_en":"A light shower chair with arms and 130 kg capacity.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"130 kg."},{"q":"¿Se puede desarmar?","a":"Sí, mediante pines y tornillos."},{"q":"¿De qué material es el asiento?","a":"Polietileno de alta densidad."},{"q":"¿Dónde descargo la ficha técnica de Silla Para Ducha Con Brazos Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"130 kg."},{"q":"Can it be taken apart?","a":"Yes, with pins and screws."},{"q":"What is the seat made of?","a":"High-density polyethylene."},{"q":"Where can I download the Konfort Plus Shower Chair with Arms datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla para ducha con brazos","silla de baño de aluminio","silla de ducha regulable","silla de ducha Konfort Plus","ayudas para el baño Colombia","ficha técnica KP1-3520L"],"seo_keywords_en":["shower chair with arms","aluminium bath chair","adjustable shower chair","Konfort Plus shower chair","bathroom aids Colombia","KP1-3520L datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC2RQMZQF2ZVDV5ARA5TBEG3I2KI?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-para-ducha-con-brazos-ref-kp1-3520l-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kp3-67034-ft.pdf',
  descripcion_larga_es = $d$El Elevador Sanitario con Seguro y Apoyabrazos está diseñado para proporcionar una solución segura y cómoda a personas con movilidad reducida. Fabricado en resina de polipropileno, este elevador sanitario es duradero, ligero y fácil de limpiar, asegurando una larga vida útil y un mantenimiento sencillo. Equipado con apoyabrazos integrados, ofrece el soporte necesario para facilitar el posicionamiento y el levantamiento del usuario, reduciendo el riesgo de caídas.

El eleva sanitario con seguro y apoyabrazos Konfort Plus está fabricado en resina de polipropileno y facilita el posicionamiento del usuario en el sanitario con el soporte adecuado. Se adapta a sanitarios clásicos, no requiere herramientas para instalarse, tiene mecanismo de ajuste y bloqueo manual seguro y apoyabrazos removibles forrados en espuma. Tiene 2 años de garantía.$d$,
  descripcion_larga_en = $d$The Konfort Plus Toilet Lift with Lock and Armrests is designed to provide a safe and comfortable solution for individuals with reduced mobility. Made from polypropylene resin, this toilet lift is durable, lightweight, and easy to clean, ensuring a long service life and simple maintenance. Equipped with integrated armrests, it provides the necessary support to facilitate user positioning and lifting, reducing the risk of falls.

The Konfort Plus toilet riser with lock and armrests is made of polypropylene resin and makes it easier to position the user on the toilet with the right support. It fits standard toilets, needs no tools to install, has a secure manual adjustment and locking mechanism and removable foam-padded armrests. It has a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP3-67034"},{"clave":"Material","grupo":"Material","valor":"Resina de polipropileno"},{"clave":"Instalación","grupo":"Instalación","valor":"Sin herramientas; bloqueo manual"},{"clave":"Garantía","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
