UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kpsempa2g1-27-ft.pdf',
  descripcion_larga_es = $d$La Superficie Especial para el Manejo de la Presión SEMP I  de Konfort Plus es una solución avanzada para la prevención de úlceras por presión en pacientes con riesgo moderado. Fabricada en PVC de grado médico y diseñada con una estructura de burbujas, esta superficie distribuye la presión de manera uniforme, evitando la compresión vascular prolongada y disminuyendo significativamente el riesgo de úlceras.

La superficie especial para el manejo de la presión SEMP I de Konfort Plus es un colchón antiescaras de burbujas fabricado en PVC de grado médico (0,3 mm), de 200 x 90 cm, con bomba regulable y manguera flexible. Evita la compresión vascular prolongada y reduce el riesgo de úlceras por presión; soporta hasta 130 kg, trabaja a 50-110 mmHg, 120 V / 60 Hz con ciclo de 12 minutos y flujo de 5 a 7 L/min. Clase IIA con registro 2024DM-0029903.$d$,
  descripcion_larga_en = $d$The Konfort Plus Pressure Management Special Surface SEMP I is an advanced solution for preventing pressure ulcers in patients at moderate risk. Constructed from medical-grade PVC with a bubble-structured design, this surface distributes pressure evenly, preventing prolonged vascular compression and significantly reducing ulcer risk.

The Konfort Plus SEMP I special pressure-management surface is an alternating-bubble anti-decubitus mattress made of medical-grade PVC (0.3 mm), 200 x 90 cm, with an adjustable pump and flexible hose. It avoids prolonged vascular compression and reduces the risk of pressure ulcers; it supports up to 130 kg, works at 50-110 mmHg, 120 V / 60 Hz with a 12-minute cycle and 5 to 7 L/min flow. Class IIA with registration 2024DM-0029903.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KPSEMPA2G1-27"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"Hasta 130 kg"},{"clave":"Tamaño","grupo":"Dimensiones","valor":"200 x 90 cm"},{"clave":"Rango de presión","grupo":"Rendimiento","valor":"50 - 110 mmHg"},{"clave":"Alimentación","grupo":"Eléctrico","valor":"120 V / 60 Hz"},{"clave":"Registro sanitario","grupo":"Regulatorio","valor":"2024DM-0029903; clase IIA"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Colchón de burbujas en PVC de grado médico para reducir el riesgo de úlceras por presión.","Bomba regulable (50-110 mmHg) con ciclo de 12 minutos y manguera flexible.","Soporta hasta 130 kg; 200 x 90 cm."],"beneficios_en":["Medical-grade PVC bubble mattress to reduce the risk of pressure ulcers.","Adjustable pump (50-110 mmHg) with a 12-minute cycle and flexible hose.","Supports up to 130 kg; 200 x 90 cm."],"valor_es":"Un colchón antiescaras de burbujas con bomba regulable.","valor_en":"An alternating-bubble anti-bedsore mattress with adjustable pump.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad de peso tiene?","a":"Hasta 130 kg."},{"q":"¿Qué presión maneja?","a":"Entre 50 y 110 mmHg."},{"q":"¿Qué medidas tiene?","a":"200 x 90 cm."},{"q":"¿Dónde descargo la ficha técnica de Superficie Especial para el Manejo de la Presión SEMP I Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What weight capacity does it have?","a":"Up to 130 kg."},{"q":"What pressure range does it handle?","a":"Between 50 and 110 mmHg."},{"q":"What are its dimensions?","a":"200 x 90 cm."},{"q":"Where can I download the Konfort Plus Pressure Management Special Surface SEMP I datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["colchón antiescaras con bomba","superficie especial para manejo de presión","colchón anti-decúbito de burbujas","colchón antiescaras Konfort Plus","prevención de úlceras por presión Colombia","ficha técnica KPSEMPA2G1-27"],"seo_keywords_en":["anti-bedsore mattress with pump","special pressure-management surface","alternating bubble anti-decubitus mattress","Konfort Plus anti-bedsore mattress","pressure ulcer prevention Colombia","KPSEMPA2G1-27 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCE7ZAUFSTGFHM5ARN2ILZMPHDB4?version=2.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'superficie-especial-para-el-manejo-de-la-presion-semp-i-ref-kpsempa2g1-27-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kbf-ab23-sm-ft.pdf',
  descripcion_larga_es = $d$La Faja Abdominal Konfort Plus está diseñada para brindar soporte y mejorar la funcionalidad de los músculos abdominales en casos postoperatorios, hernias o postparto. Elaborada con elástico libre de látex, esta faja ofrece un ajuste cómodo y seguro, gracias a su sistema de velcro reforzado. Además, cuenta con tres barras verticales en la parte posterior hechas de polipropileno, que proporcionan estabilidad adicional y apoyo a la zona lumbar.

La faja abdominal Konfort Plus (23 cm, talla S/M) está elaborada en elástico libre de látex, velcro gancho y felpa, con soporte de plaquetas posteriores de polipropileno. Brinda soporte y mejora la funcionalidad de los músculos abdominales en postoperatorios, hernias y posparto, y se ofrece en alturas de 23 y 30 cm y tallas S/M y L/XL.$d$,
  descripcion_larga_en = $d$The Konfort Plus Abdominal Belt is designed to provide support and improve the functionality of abdominal muscles in postoperative cases, hernias, or postpartum recovery. Made with latex-free elastic material, this belt offers a comfortable and secure fit through reinforced velcro. Additionally, it features three vertical polypropylene bars on the posterior side that provide additional stability and lumbar support.

The Konfort Plus abdominal binder (23 cm, size S/M) is made of latex-free elastic, hook-and-loop fastener and plush, with polypropylene rear stay supports. It provides support and improves abdominal muscle function in post-operative cases, hernias and post-partum, and is offered in 23 and 30 cm heights and sizes S/M and L/XL.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBF-AB23-SM"},{"clave":"Material","grupo":"Material","valor":"Elástico libre de látex, velcro y felpa; 3 barras posteriores de polipropileno"},{"clave":"Altura / talla","grupo":"Dimensiones","valor":"23 cm, S/M"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Elástico libre de látex con cierre de velcro ajustable.","Plaquetas posteriores de polipropileno que aportan soporte.","Indicada en postoperatorios, hernias y posparto."],"beneficios_en":["Latex-free elastic with adjustable hook-and-loop closure.","Polypropylene rear stays that add support.","Indicated for post-operative care, hernias and post-partum."],"valor_es":"Una faja abdominal de soporte para postoperatorio, hernias y posparto.","valor_en":"An abdominal support binder for post-operative care, hernias and post-partum.","preguntas_frecuentes_es":[{"q":"¿Para qué se usa?","a":"Para dar soporte abdominal en postoperatorios, hernias y posparto."},{"q":"¿Qué alturas y tallas existen?","a":"Alturas de 23 y 30 cm; tallas S/M y L/XL."},{"q":"¿Contiene látex?","a":"No, el elástico es libre de látex."},{"q":"¿Dónde descargo la ficha técnica de Faja Abdominal De 23 cm Talla S/M?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What is it used for?","a":"To provide abdominal support in post-operative care, hernias and post-partum."},{"q":"Which heights and sizes exist?","a":"Heights of 23 and 30 cm; sizes S/M and L/XL."},{"q":"Does it contain latex?","a":"No, the elastic is latex-free."},{"q":"Where can I download the Konfort Plus 23 cm Abdominal Belt Size S/M datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["faja abdominal 23 cm, talla S/M","faja abdominal postoperatoria","faja para hernias y posparto","faja Konfort Plus","ortopedia blanda Colombia","ficha técnica KBF-AB23-SM"],"seo_keywords_en":["abdominal binder 23 cm, size S/M","post-operative abdominal binder","binder for hernias and post-partum","Konfort Plus binder","soft orthopaedics Colombia","KBF-AB23-SM datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCSDDORWVIENG65MCXJES54MCRZU?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'faja-abdominal-de-23-cm-talla-s-m-ref-kbf-ab23-sm';

