UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kbf-camp-sm-ft.pdf',
  descripcion_larga_es = $d$La Faja Lumbosacra Tipo Camp de Konfort Plus está diseñada para brindar soporte y alivio en tratamientos de espóndilo artrosis, esguinces y desgarres musculares en la región lumbar. Fabricada en materiales hipoalergénicos y transpirables, esta faja incluye barras de aluminio posteriores que se adaptan a la estructura de la espalda, proporcionando una compresión eficaz que limita parcialmente los movimientos de la columna lumbar.

La faja lumbosacra tipo Camp Konfort Plus (talla S/M) está elaborada en bondeados de poliéster hipoalergénico y respirable, resortes laterales resistentes y bandas elásticas libres de látex, con velcro y varillas de aluminio posteriores contorneadas a la espalda. Está diseñada para espondiloartrosis, esguinces y desgarres musculares lumbares, escoliosis menores de 25° y postoperatorios de columna lumbosacra, comprimiendo y limitando parcialmente el movimiento lumbar.$d$,
  descripcion_larga_en = $d$The Konfort Plus Lumbosacral Camp Type Belt is designed to provide support and relief in the treatment of spondyloarthritis, sprains, and muscle tears in the lumbar region. Made from hypoallergenic and breathable materials, this belt features posterior aluminum bars that adapt to the back structure, providing effective compression that partially limits lumbar spine movements.

The Konfort Plus Camp-type lumbosacral binder (size S/M) is made of hypoallergenic, breathable bonded polyester, strong side springs and latex-free elastic bands, with hook-and-loop fastener and rear aluminium stays contoured to the back. It is designed for spondyloarthrosis, lumbar sprains and muscle tears, scoliosis under 25° and lumbosacral spine post-operative care, compressing and partially limiting lumbar movement.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBF-CAMP-SM"},{"clave":"Material","grupo":"Material","valor":"Poliéster hipoalergénico; varillas de aluminio posteriores"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Poliéster hipoalergénico y respirable con varillas de aluminio contorneadas.","Indicada en espondiloartrosis, esguinces, desgarres lumbares y escoliosis menores de 25°.","Compresión y limitación parcial del movimiento lumbar tras cirugía de columna."],"beneficios_en":["Hypoallergenic, breathable polyester with contoured aluminium stays.","Indicated for spondyloarthrosis, sprains, lumbar tears and scoliosis under 25°.","Compression and partial limitation of lumbar movement after spine surgery."],"valor_es":"Una faja lumbosacra con varillas de aluminio para tratamientos lumbares.","valor_en":"A lumbosacral binder with aluminium stays for lumbar treatments.","preguntas_frecuentes_es":[{"q":"¿Para qué patologías está indicada?","a":"Espondiloartrosis, esguince y desgarre muscular lumbar, escoliosis menores de 25° y postoperatorios de columna lumbosacra."},{"q":"¿De qué está hecha?","a":"Poliéster hipoalergénico y respirable, resortes laterales y bandas elásticas libres de látex."},{"q":"¿Qué tallas existen?","a":"S/M y L/XL."},{"q":"¿Dónde descargo la ficha técnica de Faja Lumbo Sacra Tipo Camp Talla S/M?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Which conditions is it indicated for?","a":"Spondyloarthrosis, lumbar sprain and muscle tear, scoliosis under 25° and lumbosacral spine post-operative care."},{"q":"What is it made of?","a":"Hypoallergenic, breathable polyester, side springs and latex-free elastic bands."},{"q":"Which sizes exist?","a":"S/M and L/XL."},{"q":"Where can I download the Konfort Plus Lumbosacral Camp Type Belt Size S/M datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["faja lumbosacra tipo Camp talla S/M","faja lumbar con varillas","faja para lumbalgia","faja Konfort Plus","ortopedia blanda Colombia","ficha técnica KBF-CAMP-SM"],"seo_keywords_en":["Camp-type lumbosacral binder size S/M","lumbar binder with stays","binder for low back pain","Konfort Plus binder","soft orthopaedics Colombia","KBF-CAMP-SM datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCR2SQBHTJFNBBPD4IFFZC43WII4?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'faja-lumbo-sacra-tipo-camp-talla-s-m-ref-kbf-camp-sm';

