UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kb-ra-ft.pdf',
  descripcion_larga_es = $d$La Rodillera Universal Konfort Plus es una solución ideal para quienes necesitan soporte y alivio en la articulación de la rodilla. Fabricada en neopreno de alta calidad, esta rodillera proporciona calor terapéutico que ayuda a aliviar el dolor y acelerar la recuperación de lesiones como subluxaciones de la rótula y esguinces leves.

La rodillera ajustable talla universal Konfort Plus está elaborada en neopreno (caucho multidireccional recubierto en nailon-poliéster) con cierre de velcro, y aporta calor a la articulación. Tiene orificio patelar que ayuda a mantener la rótula alineada. Está indicada en la recuperación de subluxaciones de rótula, esguinces leves de rodilla o como soporte deportivo.$d$,
  descripcion_larga_en = $d$The Konfort Plus Universal Knee Brace is an ideal solution for those requiring support and relief in the knee joint. Made of high-quality neoprene, this knee brace provides therapeutic heat that helps relieve pain and accelerate recovery from injuries such as patellar subluxations and mild sprains.

The Konfort Plus adjustable universal-size knee support is made of neoprene (multidirectional rubber covered with nylon-polyester) with hook-and-loop closure, and provides warmth to the joint. It has a patellar opening that helps keep the kneecap aligned. It is indicated for recovery from patellar subluxations, mild knee sprains or as sports support.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KB-RA"},{"clave":"Material","grupo":"Material","valor":"Neopreno recubierto en nailon-poliéster y velcro"},{"clave":"Talla","grupo":"Talla","valor":"Universal ajustable"},{"clave":"Color","grupo":"Color","valor":"Negro"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Neopreno que da calor a la articulación y velcro ajustable.","Orificio patelar que ayuda a mantener la rótula alineada.","Para subluxaciones de rótula, esguinces leves o soporte deportivo."],"beneficios_en":["Neoprene that warms the joint and adjustable hook-and-loop closure.","Patellar opening that helps keep the kneecap aligned.","For patellar subluxations, mild sprains or sports support."],"valor_es":"Una rodillera de neopreno con orificio patelar y ajuste universal.","valor_en":"A neoprene knee brace with patellar opening and universal fit.","preguntas_frecuentes_es":[{"q":"¿Qué talla es?","a":"Talla universal ajustable con velcro."},{"q":"¿Para qué se usa?","a":"Recuperación de subluxaciones de rótula, esguinces leves de rodilla o soporte deportivo."},{"q":"¿De qué material es?","a":"Neopreno con velcro."},{"q":"¿Dónde descargo la ficha técnica de Rodillera Universal Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What size is it?","a":"Universal size adjustable with hook-and-loop."},{"q":"What is it used for?","a":"Recovery from patellar subluxations, mild knee sprains or sports support."},{"q":"What material is it?","a":"Neoprene with hook-and-loop."},{"q":"Where can I download the Konfort Plus Universal Knee Brace datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["rodillera ajustable talla universal","rodillera de neopreno","soporte de rodilla con orificio patelar","rodillera Konfort Plus","ortopedia blanda Colombia","ficha técnica KB-RA"],"seo_keywords_en":["adjustable universal knee support","neoprene knee brace","knee support with patellar opening","Konfort Plus knee brace","soft orthopaedics Colombia","KB-RA datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCC5EPGEAM3RCQ7HZYV3TIWNDI7Q?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
