UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbc-aa-ft.pdf',
  descripcion_larga_es = $d$El Cabestrillo Adulto de Konfort Plus está diseñado para proporcionar un soporte confiable en casos de traumas, inestabilidad, fracturas, esguinces y lesiones de hombro y codo. Fabricado en resistente tela de dril y reforzado con reatas y hebillas, este cabestrillo garantiza una inmovilización cómoda y segura, con un diseño que incluye un inmovilizador circular en la espalda para mayor estabilidad.

El cabestrillo adulto azul profundo Konfort Plus está elaborado en tela de algodón con reatas y bondeado de poliéster, y brinda soporte en traumas e inestabilidad con un inmovilizador circular a la espalda. Está indicado en fracturas, esguinces y lesiones de hombro y codo; se fija por medio de reatas y hebillas.$d$,
  descripcion_larga_en = $d$The Konfort Plus Adult Sling is designed to provide reliable support for trauma, instability, fractures, sprains, and shoulder and elbow injuries. Made from durable drill fabric and reinforced with straps and buckles, this sling ensures comfortable and secure immobilization, featuring a circular back immobilizer for enhanced stability.

The Konfort Plus adult deep blue sling is made of cotton fabric with polyester straps and bonding, and gives support in trauma and instability with a circular immobiliser around the back. It is indicated for fractures, sprains and shoulder and elbow injuries; it is fastened with straps and buckles.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBC-AA"},{"clave":"Material","grupo":"Material","valor":"Algodón (dril) con reatas y bondeado de poliéster"},{"clave":"Sujeción","grupo":"Sujeción","valor":"Reatas y hebillas"},{"clave":"Registro sanitario","grupo":"Regulatorio","valor":"2018DM-0018516"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Soporte en traumas e inestabilidad con inmovilizador circular a la espalda.","Indicado en fracturas, esguinces y lesiones de hombro y codo.","Algodón con reatas de poliéster, ajustable con hebillas."],"beneficios_en":["Support in trauma and instability with circular back immobiliser.","Indicated for fractures, sprains and shoulder and elbow injuries.","Cotton with polyester straps, adjustable with buckles."],"valor_es":"Un cabestrillo de algodón para inmovilizar hombro y codo.","valor_en":"A cotton sling to immobilise the shoulder and elbow.","preguntas_frecuentes_es":[{"q":"¿Para qué lesiones sirve?","a":"Fracturas, esguinces y lesiones de hombro y codo."},{"q":"¿Cómo se ajusta?","a":"Por medio de reatas y hebillas."},{"q":"¿Hay versión pediátrica?","a":"Sí, existe la versión pediátrica en azul y rosado y la de adulto en azul profundo."},{"q":"¿Dónde descargo la ficha técnica de Cabestrillo Adulto Color Azul Profundo Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Which injuries is it for?","a":"Fractures, sprains and shoulder and elbow injuries."},{"q":"How is it adjusted?","a":"With straps and buckles."},{"q":"Is there a paediatric version?","a":"Yes, the paediatric version comes in blue and pink and the adult in deep blue."},{"q":"Where can I download the Konfort Plus Adult Sling Deep Blue datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["cabestrillo adulto azul profundo","cabestrillo para hombro y codo","cabestrillo de algodón","cabestrillo Konfort Plus","ortopedia blanda Colombia","ficha técnica KBC-AA"],"seo_keywords_en":["adult deep blue sling","shoulder and elbow sling","cotton arm sling","Konfort Plus sling","soft orthopaedics Colombia","KBC-AA datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC2TIO6ZNC4NC25CNNR6FE22SU34?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
